/**
 * Synthetic trace results, generated by running the real engine
 * (`backend/scripts/export_demo_data.py`). Do not edit the JSON by hand.
 */
import type { InvestigationReport } from "../api/report";
import type { TraceGraphResponse, TraceStatusResponse } from "../api/types";
import raw from "./data/scenarios.json";

export interface Scenario {
  key: string;
  title: string;
  description: string;
  seed: string;
  trace: TraceStatusResponse;
  graph: TraceGraphResponse;
  report: InvestigationReport;
}

export const SCENARIOS = raw as unknown as Scenario[];

export const scenarioByKey = (key: string) => SCENARIOS.find((s) => s.key === key);
export const scenarioBySeed = (seed: string) => SCENARIOS.find((s) => s.seed === seed);
